<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ArrowLeft, Edit3, Eye, EyeOff, Image, LogOut, Plus, RefreshCw, Save, Store, Tags, Utensils } from 'lucide-vue-next'
import { useRouter } from 'vue-router'
import { useSessionStore } from '../stores/session'
import { loadAdminCatalog, saveCategory, saveProduct, saveRestaurant } from '../services/adminCatalogService'

const router = useRouter(); const session = useSessionStore()
const tab = ref('restaurants'); const loading = ref(true); const saving = ref(false); const error = ref(''); const success = ref(''); const editingId = ref(null)
const catalog = reactive({ restaurants: [], categories: [], products: [], zones: [] })
const restaurantForm = reactive({ zona_id: '', nombre: '', tipo_comida: 'Otros', descripcion: '', imagen_url: '', banner_url: '', calificacion: 0, cantidad_resenas: 0, tiempo_preparacion_min: 30, activo: true })
const categoryForm = reactive({ restaurante_id: '', nombre: '', orden: 0, activa: true })
const productForm = reactive({ restaurante_id: '', categoria_id: '', nombre: '', descripcion: '', precio: 0, imagen_url: '', disponible: true })
const selectedCategories = computed(() => catalog.categories.filter((category) => category.restaurante_id === productForm.restaurante_id))

function resetForm(type) {
  editingId.value = null; error.value = ''; success.value = ''
  if (type === 'restaurant') Object.assign(restaurantForm, { zona_id: catalog.zones[0]?.id || '', nombre: '', tipo_comida: 'Otros', descripcion: '', imagen_url: '', banner_url: '', calificacion: 0, cantidad_resenas: 0, tiempo_preparacion_min: 30, activo: true })
  if (type === 'category') Object.assign(categoryForm, { restaurante_id: catalog.restaurants.find((item) => item.activo)?.id || '', nombre: '', orden: 0, activa: true })
  if (type === 'product') Object.assign(productForm, { restaurante_id: catalog.restaurants.find((item) => item.activo)?.id || '', categoria_id: '', nombre: '', descripcion: '', precio: 0, imagen_url: '', disponible: true })
}
function edit(type, item) { editingId.value = item.id; error.value = ''; success.value = ''; if (type === 'restaurant') Object.assign(restaurantForm, item); if (type === 'category') Object.assign(categoryForm, item); if (type === 'product') Object.assign(productForm, item) }
async function submit(type) { saving.value = true; error.value = ''; success.value = ''; try { if (type === 'restaurant') await saveRestaurant(restaurantForm, editingId.value); if (type === 'category') await saveCategory(categoryForm, editingId.value); if (type === 'product') await saveProduct(productForm, editingId.value); success.value = 'Cambios guardados.'; await load(); resetForm(type) } catch (saveError) { error.value = saveError.message || 'No se pudieron guardar los cambios.' } finally { saving.value = false } }
async function load() { loading.value = true; error.value = ''; try { Object.assign(catalog, await loadAdminCatalog()) } catch (loadError) { error.value = loadError.message || 'No se pudo cargar el catálogo.' } finally { loading.value = false } }
async function logout() { await session.signOut(); router.replace('/') }
onMounted(async () => { await load(); resetForm('restaurant') })
</script>

<template>
  <main class="admin-page">
    <header class="admin-header"><button class="icon-button" aria-label="Volver" @click="router.push('/')"><ArrowLeft :size="25" /></button><div><span class="admin-kicker">ADMINISTRACIÓN</span><h1>Catálogo</h1></div><button class="icon-button" aria-label="Cerrar sesión" @click="logout"><LogOut :size="21" /></button></header>
    <div class="admin-tabs"><button :class="{ active: tab === 'restaurants' }" @click="tab = 'restaurants'"><Store :size="18" /> Restaurantes</button><button :class="{ active: tab === 'categories' }" @click="tab = 'categories'"><Tags :size="18" /> Categorías</button><button :class="{ active: tab === 'products' }" @click="tab = 'products'"><Utensils :size="18" /> Productos</button></div>
    <section class="admin-content">
      <div class="admin-status"><p v-if="loading">Cargando catálogo…</p><p v-else-if="error" class="admin-error">{{ error }}</p><p v-else-if="success" class="admin-success">{{ success }}</p><button class="admin-refresh" @click="load"><RefreshCw :size="17" /></button></div>

      <template v-if="tab === 'restaurants'">
        <form class="admin-form" @submit.prevent="submit('restaurant')"><div class="admin-section-title"><div><h2>{{ editingId ? 'Editar restaurante' : 'Nuevo restaurante' }}</h2><p>La portada y el logotipo se registran como URLs de imagen.</p></div><button type="button" class="text-button" @click="resetForm('restaurant')">Limpiar</button></div><div class="form-grid"><label>Nombre<input v-model="restaurantForm.nombre" required /></label><label>Zona<select v-model="restaurantForm.zona_id" required><option v-for="zone in catalog.zones" :key="zone.id" :value="zone.id">{{ zone.nombre }}</option></select></label><label>Tipo de restaurante<select v-model="restaurantForm.tipo_comida" required><option>Comida mexicana</option><option>Comida china</option><option>Hamburguesas</option><option>Pizzas</option><option>Pollo</option><option>Comida italiana</option><option>Comida asiática</option><option>Otros</option></select></label><label class="full">Descripción<textarea v-model="restaurantForm.descripcion" rows="2" /></label><label>Logotipo (URL)<input v-model="restaurantForm.imagen_url" type="url" /></label><label>Portada (URL)<input v-model="restaurantForm.banner_url" type="url" /></label><label>Calificación<input v-model="restaurantForm.calificacion" type="number" min="0" max="5" step="0.1" /></label><label>Reseñas<input v-model="restaurantForm.cantidad_resenas" type="number" min="0" /></label><label>Entrega (minutos)<input v-model="restaurantForm.tiempo_preparacion_min" type="number" min="1" /></label><label class="check-label"><input v-model="restaurantForm.activo" type="checkbox" /> Activo</label></div><div v-if="restaurantForm.imagen_url || restaurantForm.banner_url" class="admin-preview"><img v-if="restaurantForm.imagen_url" :src="restaurantForm.imagen_url" alt="Vista previa del logotipo" /><img v-if="restaurantForm.banner_url" :src="restaurantForm.banner_url" alt="Vista previa de portada" /></div><button class="admin-primary" :disabled="saving"><Save :size="18" /> {{ saving ? 'Guardando…' : 'Guardar restaurante' }}</button></form>
        <div class="admin-list"><h2>Restaurantes registrados ({{ catalog.restaurants.length }})</h2><article v-for="restaurant in catalog.restaurants" :key="restaurant.id" class="admin-row"><div class="admin-row__image"><img :src="restaurant.imagen_url || '/logos/logo.png'" :alt="restaurant.nombre" /></div><div><strong>{{ restaurant.nombre }}</strong><span>{{ restaurant.zonas?.nombre || 'Sin zona' }} · {{ restaurant.tiempo_preparacion_min }} min</span><small :class="restaurant.activo ? 'status-active' : 'status-inactive'">{{ restaurant.activo ? 'Activo' : 'Inactivo' }}</small></div><button class="row-action" @click="edit('restaurant', restaurant)"><Edit3 :size="17" /></button></article></div>
      </template>

      <template v-if="tab === 'categories'"><form class="admin-form" @submit.prevent="submit('category')"><div class="admin-section-title"><div><h2>{{ editingId ? 'Editar categoría' : 'Nueva categoría' }}</h2><p>Cada categoría pertenece a un restaurante.</p></div><button type="button" class="text-button" @click="resetForm('category')">Limpiar</button></div><div class="form-grid"><label>Restaurante<select v-model="categoryForm.restaurante_id" required><option v-for="restaurant in catalog.restaurants" :key="restaurant.id" :value="restaurant.id">{{ restaurant.nombre }}</option></select></label><label>Nombre<input v-model="categoryForm.nombre" required /></label><label>Orden<input v-model="categoryForm.orden" type="number" min="0" /></label><label class="check-label"><input v-model="categoryForm.activa" type="checkbox" /> Activa</label></div><button class="admin-primary" :disabled="saving"><Save :size="18" /> Guardar categoría</button></form><div class="admin-list"><h2>Categorías ({{ catalog.categories.length }})</h2><article v-for="category in catalog.categories" :key="category.id" class="admin-row"><div class="admin-row__icon"><Tags :size="20" /></div><div><strong>{{ category.nombre }}</strong><span>{{ category.restaurantes?.nombre || 'Sin restaurante' }} · Orden {{ category.orden }}</span><small :class="category.activa ? 'status-active' : 'status-inactive'">{{ category.activa ? 'Activa' : 'Inactiva' }}</small></div><button class="row-action" @click="edit('category', category)"><Edit3 :size="17" /></button></article></div></template>

      <template v-if="tab === 'products'"><form class="admin-form" @submit.prevent="submit('product')"><div class="admin-section-title"><div><h2>{{ editingId ? 'Editar producto' : 'Nuevo producto' }}</h2><p>El producto se publica dentro de una categoría del restaurante elegido.</p></div><button type="button" class="text-button" @click="resetForm('product')">Limpiar</button></div><div class="form-grid"><label>Restaurante<select v-model="productForm.restaurante_id" required><option v-for="restaurant in catalog.restaurants" :key="restaurant.id" :value="restaurant.id">{{ restaurant.nombre }}</option></select></label><label>Categoría<select v-model="productForm.categoria_id" required><option v-for="category in selectedCategories" :key="category.id" :value="category.id">{{ category.nombre }}</option></select></label><label>Nombre<input v-model="productForm.nombre" required /></label><label>Precio<input v-model="productForm.precio" type="number" min="0" step="0.01" required /></label><label class="full">Descripción<textarea v-model="productForm.descripcion" rows="2" /></label><label class="full">Fotografía (URL)<input v-model="productForm.imagen_url" type="url" /></label><label class="check-label"><input v-model="productForm.disponible" type="checkbox" /> Disponible</label></div><button class="admin-primary" :disabled="saving"><Save :size="18" /> Guardar producto</button></form><div class="admin-list"><h2>Productos ({{ catalog.products.length }})</h2><article v-for="product in catalog.products" :key="product.id" class="admin-row"><div class="admin-row__image"><img :src="product.imagen_url || '/logos/logo.png'" :alt="product.nombre" /></div><div><strong>{{ product.nombre }}</strong><span>{{ product.restaurantes?.nombre || 'Sin restaurante' }} · {{ product.categorias?.nombre || 'Sin categoría' }} · ${{ Number(product.precio).toFixed(2) }}</span><small :class="product.disponible ? 'status-active' : 'status-inactive'">{{ product.disponible ? 'Disponible' : 'No disponible' }}</small></div><button class="row-action" @click="edit('product', product)"><Edit3 :size="17" /></button></article></div></template>
    </section>
  </main>
</template>
